function CONSENSUS(observers T_1..T_k):
    R <- open-sets(T_1)
    for i = 2 to k:
        R <- R intersect open-sets(T_i)
    return R   # a set is real-open iff it is open in every observer

function COLLAPSE_TO_TWO(T_1..T_k, carrier):
    if k <= 2: return T_1..T_k
    seed <- union of open-sets(T_2..T_k)
    merged <- GENERATE_TOPOLOGY(seed, carrier)
    return [T_1, merged]

function GENERATE_TOPOLOGY(seed, carrier):
    O <- seed union {empty, carrier}
    repeat until fixpoint:
        for u, v in O: add u&v and u|v to O
    return O

